entries[94522] = { ["name"] = "Talisman des Blutdurstes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Talisman des Blutdurstes (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, Euer Tempo 10 Sek. lang um 6 zu erhöhen. Dieser Effekt ist bis zu 5-mal stapelbar. (Ungefähr 3.50 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94523] = { ["name"] = "Finsteres Juju", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Finsteres Juju (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Wenn Eure Angriffe treffen, besteht eine Chance, dass Ihr 10 Sek. lang 21 Beweglichkeit erhaltet und 3 Voodoognome beschwört. (Ungefähr 1.10 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94524] = { ["name"] = "Unfehlbarer Blick des Lei Shen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Unfehlbarer Blick des Lei Shen (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, Eure kritische Trefferchance 4 Sek. lang um 100% zu erhöhen. (Ungefähr 0.01 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94525] = { ["name"] = "Gestohlenes Relikt von Zuldazar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Gestohlenes Relikt von Zuldazar (1)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Eure hilfreichen Zauber haben eine Chance, Euch den Segen von Zuldazar zu gewähren. Dieser Effekt ist bis zu 6-mal stapelbar. (Ungefähr 2.89 Auslösungen pro Minute)\nBenutzen: Verbraucht alle Segen von Zuldazar, um das Ziel abzuschirmen, und absorbiert pro verbrauchtem Segen 3 Schaden. Hält 15 Sek. lang an. (20 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[94526] = { ["name"] = "Funken von Zandalar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Funken von Zandalar (1)\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Eure Angriffe haben eine Chance, Euch einen Funken von Zandalar zu gewähren. Sobald Ihr 10 dieser Funken angesammelt habt, verwandelt Ihr Euch 10 Sek. lang in einen Krieger der Zandalari. In dieser Gestalt ist Eure Stärke um 21 erhöht. (Ungefähr 11.10 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94527] = { ["name"] = "Ji-Kuns Aufwind", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Ji-Kuns Aufwind (1)\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Nahkampfangriffe, die Eure Gesundheit auf unter 35% verringern, führen dazu, dass Ihr sofort um 12 geheilt werdet. Kann maximal einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:" }
entries[94528] = { ["name"] = "Seelenbarriere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Seelenbarriere (1)\nSchmuck\n+6 Ausdauer\nBenutzen: Absorbiert jedes Mal, wenn Ihr körperlichen Schaden erleidet, bis zu 3 Schaden. Absorbiert maximal bis zu ( 3 * 5) Schaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[94529] = { ["name"] = "Blick der Zwillinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Blick der Zwillinge (1)\nSchmuck\n+4 Stärke\nAnlegen: Eure erzielten kritischen Treffer haben eine Chance, Euren kritischen Trefferwert 20 Sek. lang um 12 zu erhöhen. Dieser Effekt ist bis zu 3-mal stapelbar. (Ungefähr 0.72 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94530] = { ["name"] = "Blitz-verzauberter Kelch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Blitz-verzauberter Kelch (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euch 'Unendliche Macht' zu verleihen. Sobald 6 Aufladungen von 'Unendliche Macht' erreicht sind, heilt Ihr sofort das am schwersten verletzte Gruppenmitglied in der Nähe um 16 Gesundheit. (Ungefähr 5.78 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94531] = { ["name"] = "Cha-Yes brillante Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Cha-Yes brillante Essenz (1)\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nAnlegen: Wenn Eure Zauber kritischen Schaden verursachen, besteht eine Chance, dass Eure Intelligenz 10 Sek. lang um 21 erhöht wird. (Ungefähr 0.85 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[94532] = { ["name"] = "Rune der Neuerschaffung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Rune der Neuerschaffung (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Wenn Eure Angriffe treffen, besteht eine Chance, den Effekt 'Neuerschaffung' auszulösen. Dieser Effekt wandelt 10 Sek. lang den Wert der zwei niedrigsten aus Euren drei Attributen kritischer Trefferwert, Tempo und Meisterschaft zum höchsten dieser drei Attribute um und verdoppelt ihn außerdem. (Ungefähr 0.01 Auslösungen pro Minute, 10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[94535] = { ["name"] = "Gegrillter Dinosaurierschenkel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Meisterschaft.\nVerkaufspreis:" }
entries[94536] = { ["name"] = "Unbeschädigter Terrorhornbalg", ["text"] = "Benutzen: Tarnt Euch als ein Terrorhorn und verringert 10 Min. lang die Distanz, auf die Gegner Euch entdecken können, während Ihr Euch auf der Insel der Riesen befindet.\n\"Sogar die Hörner sind noch dran!\"\nVerkaufspreis:" }
entries[94552] = { ["name"] = "Pläne: Donnerstahlbarren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Donnerstahlbarren.\nStellt einen Donnerstahlbarren aus Geistereisenbarren her. Dabei könnt Ihr zusätzliches Wissen über Geistereisen erlangen und einen Schmiedeplan entdecken, den Ihr noch nicht kennt. Dieser Vorgang kann nur einmal am Tag durchgeführt werden.\nBenötigt Schmiedekunst von Pandaria (1)\n\nDonnerstahlbarren\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Wird von Schmieden verwendet, um mächtige Objekte herzustellen.\"\nVerkaufspreis:\nBenötigt Geistereisenbarren (10)" }
entries[94553] = { ["name"] = "Notizen über Donnerstahl", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[94566] = { ["name"] = "Lade des Glücks", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[94567] = { ["name"] = "Pläne: Wiedergeborener Donner", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung des wiedergeborenen Donners.\nBeim Schmieden dieser Waffe erlernt Ihr das Erschaffen des wiedergeborenen Donnergrolls.\nBenötigt Schmiedekunst von Pandaria (1)\n\nWiedergeborener Donner\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n9 - 13 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Donnerstahlbarren (5), Lebendiger Stahl (3), Geist der Harmonie (3)" }
entries[94568] = { ["name"] = "Pläne: Wiedergeborene Drachenfaust", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung der wiedergeborenen Drachenfaust.\nBeim Schmieden dieser Waffe erlernt Ihr das Erschaffen des wiedergeborenen Drachenmals.\nBenötigt Schmiedekunst von Pandaria (1)\n\nWiedergeborene Drachenfaust\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+12 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Donnerstahlbarren (5), Lebendiger Stahl (2), Geist der Harmonie (3)" }
entries[94569] = { ["name"] = "Pläne: Wiedergeborene Mondsichel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung der wiedergeborenen Mondsichel.\nBeim Schmieden dieser Waffe erlernt Ihr das Erschaffen des wiedergeborenen Mondspaltbeils.\nBenötigt Schmiedekunst von Pandaria (1)\n\nWiedergeborene Mondsichel\nWird beim Anlegen gebunden\nZweihändig Axt\n7 - 15 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Stärke\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Donnerstahlbarren (5), Lebendiger Stahl (3), Geist der Harmonie (3)" }
entries[94570] = { ["name"] = "Pläne: Wiedergeborene Planaraxt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung der wiedergeborenen Planaraxt.\nBeim Schmieden dieser Waffe erlernt Ihr das Erschaffen der wiedergeborenen schwarzen Planaraxt.\nBenötigt Schmiedekunst von Pandaria (1)\n\nDie wiedergeborene Planaraxt\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Donnerstahlbarren (5), Lebendiger Stahl (2), Geist der Harmonie (3)" }
