entries[94593] = { ["name"] = "Geheimnisse des Kaiserreiches", ["text"] = "Wird beim Aufheben gebunden\n\"Eine uralte Steintafel, die die Ursprünge und die Organisation des ersten Mogureiches beschreibt.\"" }
entries[94594] = { ["name"] = "Runenstein der Titanen", ["text"] = "Wird beim Aufheben gebunden\n\"Schwach leuchtende Symbole bewegen sich geräuschlos über die Oberfläche dieses vollkommen glatten Steins. Ihr versteht die Sprache nicht, aber Furorion kann sie mit Sicherheit lesen.\"" }
