entries[94604] = { ["name"] = "Brennende Saat", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nKlassen: Druide\nBenutzen: Nutzt die Essenz des Feuers, die Druiden der Flamme gewährt wurde. (2 Sek. Abklingzeit)\n\"Die Macht, die diesem Samen entströmt, kennzeichnet ihn eindeutig als Kind von Nordrassil, das von den Flammen der Feuerlande geschwärzt wurde.\"" }
entries[94605] = { ["name"] = "Wildes Pterrorschwingenjungtier", ["text"] = "Questgegenstand\nEinzigartig\n\"Kaum ist er in Euren Taschen verstaut, wird er überraschend handzahm.\"" }
