entries[94835] = { ["name"] = "Küken von Ji-Kun", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Küken von Ji-Kun beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[94847] = { ["name"] = "Chefingenieur Jards Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Ingenieurskunst (600)\n\"Der bekannte Ingenieur Jard hat dieses Tagebuch auf seinen Reisen in Pandaria verloren. Vielleicht sind einige der Aufzeichnungen für Euch von Interesse.\"\n<Zum Öffnen rechtsklicken>" }
entries[94867] = { ["name"] = "Herz des Donnerkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine geschwärzte, verschrumpelte Hülse, die trotz allem aufgrund einer seltsamen elektrischen Spannung noch immer schlägt.\"" }
entries[94880] = { ["name"] = "Bauplan: Himmelsgolem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung des Himmelsgolems.\nBenötigt Ingenieurskunst (600)\n\nHimmelsgolem\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man den Himmelsgolem fliegt. Das ist ein Flugreittier.\nSteigt in einen Himmelsgolem, wodurch Ihr schnell fliegen könnt. Die Krallen sind überraschend präzise und können von Kräuterkundigen zum Kräuterpflücken verwendet werden. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Als glorreiche Leistung der Ingenieurskunst hebt der Himmelsgolem die traditionelle Schreddertechnologie auf ein neues Niveau (und in die Höhe!).\"Beruf:\nIngenieurskunstBenötigt Jards merkwürdige Energiequelle (30), Lebendiger Stahl (30)" }
entries[94893] = { ["name"] = "Bauplan: Pierre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Pierre.\nBenötigt Ingenieurskunst (600)\n\nPierre\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Pierre beschwören oder wieder freigeben. Wenn Ihr ihm einen Moment gebt, um sich aufzuwärmen, gibt er ein vorzügliches Kochfeuer ab.\n80 ( 80)\nBenötigt Jards merkwürdige Energiequelle (15), Lebendiger Stahl (15)" }
entries[94894] = { ["name"] = "Bauplan: Fortschrittliche Kühleinheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung einer fortschrittlichen Kühleinheit.\nBenötigt Ingenieurskunst (600)\n\nFortschrittliche Kühleinheit\nWird beim Anlegen gebunden\n36 Platz Kochtasche\nBenötigt Jards merkwürdige Energiequelle (5), Lebendiger Stahl (5)" }
entries[94903] = { ["name"] = "Pierre", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Pierre beschwören oder wieder freigeben. Wenn Ihr ihm einen Moment gebt, um sich aufzuwärmen, gibt er ein vorzügliches Kochfeuer ab.\n80 ( 80)" }
