entries[95041] = { ["name"] = "Wolkenschlange des bösartigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des bösartigen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schuppen dieser Wolkenschlangen haben die Farbe von... Wolken, könnte man sagen.\"\nKlassisch" }
entries[95050] = { ["name"] = "DER Messingschlagring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nBenötigt eine Horde-Rasse\nBenutzen: Teleportiert Euch in die Shlae'gararena. (1 Stunde Abklingzeit)\n\"Hiermit ist sichergestellt, dass Ihr auch weiterhin fest zuschlagen könnt.\"" }
entries[95051] = { ["name"] = "DER Messingschlagring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nBenötigt eine Allianz-Rasse\nBenutzen: Teleportiert Euch zu Bizmos Boxbar. (1 Stunde Abklingzeit)\n\"Hiermit ist sichergestellt, dass Ihr auch weiterhin fest zuschlagen könnt.\"" }
entries[95052] = { ["name"] = "Arkaner Treibstoff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (60)\nBenutzen: Verbraucht einen arkanen Fokus, um Euch vorwärts zu katapultieren. Kann nur während des Szenarios Schatzkammer des Donnerkönigs verwendet werden. (10 Sek. Abklingzeit)\nBenötigt Offensive der Kirin Tor\n- Respektvoll\nVerkaufspreis:" }
entries[95053] = { ["name"] = "Ein gewöhnlicher Stein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Kann verwendet werden, um im Szenario Schatzkammer des Donnerkönigs einen Gegner abzulenken oder eine Falle zu entschärfen. (10 Sek. Abklingzeit)\nBenötigt Offensive der Kirin Tor\n- Wohlwollend\nVerkaufspreis:" }
entries[95054] = { ["name"] = "Trank des leichten Fußes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Kann verwendet werden, um während des Szenarios Schatzkammer des Donnerkönigs über Bodenkachelfallen zu levitieren, mit verringerter Geschwindigkeit zu fallen und sich über Wasser zu bewegen. Erlittener Schaden bricht den Effekt ab. (10 Sek. Abklingzeit)\nBenötigt Offensive der Kirin Tor\n- Freundlich\nVerkaufspreis:" }
entries[95055] = { ["name"] = "Frostrunenfalle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Platziert eine Rune, die das nächste gegnerische Ziel, das darauftritt, für 20 Sek. einfriert. Kann nur im Szenario Schatzkammer des Donnerkönigs eingesetzt werden. (10 Sek. Abklingzeit)\nBenötigt Offensive der Kirin Tor\n- Respektvoll\nVerkaufspreis:" }
entries[95056] = { ["name"] = "Verwandlungsschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Verformt mit Hilfe von Magie den Schlüssel, sodass er in jedes uralte Tor in der Zitadelle des Donnerkönigs im Szenario Schatzkammer des Donnerkönigs passt. (5 Min Abklingzeit)\nBenötigt Offensive der Kirin Tor\n- Ehrfürchtig\nVerkaufspreis:" }
entries[95057] = { ["name"] = "Zügel der donnernden Kobaltwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Kobaltwolkenschlange oder gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dies ist ein Nachfahre des jähzornigen Nalak. Blitze schießen aus seinen Schuppen und kriechen über den Sattel. Wagt Ihr es, aufzusitzen?\"\nBeute von:\nNalak\nOrt:\nInsel des Donners" }
entries[95059] = { ["name"] = "Kralle von Ji-Kun", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Kralle von Ji-Kun oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Obwohl Ji-Kun die misslungenen Kreationen der Fleischformer der Mogu verschlang, gibt ihr Nachwuchs sich mit gewöhnlicheren Leichen zufrieden.\"\nBeute von:\nJi-Kun\nZone:\nDer Thron des Donners" }
