entries[95426] = { ["name"] = "Fürst Ahunes Frostsichel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nBenutzen: Lasst die Kälte der Frostsichel durch Euch hindurchfließen. (1 Min Abklingzeit)\n\"Ein kalter Hauch geht von dieser Sichel aus.\"\nVerkaufspreis:" }
