entries[95432] = { ["name"] = "Blitzlanze", ["text"] = "Questgegenstand\nBenutzen: Rammt Nalak dem Sturmfürsten die Blitzlanze in den Leib, um seine Essenz in die Waffe zu ziehen. (1 Min Abklingzeit)\n\"Eine große Macht schlummert darin.\"" }
