entries[95470] = { ["name"] = "Vorlage: Das Schlangenherz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch das Schleifen des Schlangenherzens.\nKombiniert einmal pro Tag Serpentine zu einem Schlangenherz.\nBenötigt Juwelierskunst von Pandaria\n(1)\n\nDas Schlangenherz\nWird beim Aufheben gebunden\n\"Etwas leuchtet in seinem Innern.\"\n<Zum Öffnen rechtsklicken>\nBenötigt Serpentin (3)" }
