entries[95564] = { ["name"] = "Zügel des goldenen Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares goldenes Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Offensive der Kirin Tor\n- Ehrfürchtig\nVerkaufspreis:\n\"An beiden Enden spitz und in der Mitte hinterlistig. Nur Trolle könnten glauben, dass dies eine gute Idee war.\"\nVerkäufer:\nHiren Lehrensang\nZone:\nInsel des Donners\nFraktion:\nOffensive der Kirin Tor - Ehrfürchtig\nKosten:" }
entries[95565] = { ["name"] = "Zügel des purpurroten Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares purpurrotes Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Sonnenhäscheransturm\n- Ehrfürchtig\nVerkaufspreis:\n\"Natürlich mussten die Blutelfen sich ausgerechnet das Rote aussuchen.\"\nVerkäufer:\nVasarin Morgenröte\nZone:\nInsel des Donners\nFraktion:\nSonnenhäscheransturm - Ehrfürchtig\nKosten:" }
